import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import Webcam from "react-webcam";

function JoinExam() {
  const [exams, setExams] = useState([]);
  const [selectedExam, setSelectedExam] = useState(null);
  const [idImage, setIdImage] = useState(null);
  const [verificationMessage, setVerificationMessage] = useState("");
  const [verified, setVerified] = useState(false);

  const webcamRef = useRef(null);
  const token = localStorage.getItem("token");

  // 📚 Lade alle verfügbaren Prüfungen
  useEffect(() => {
    axios
      .get("http://127.0.0.1:8000/api/students/exams/", {
        headers: { Authorization: `Token ${token}` },
      })
      .then((res) => setExams(res.data))
      .catch((err) => console.error(err));
  }, [token]);

  // 📷 Nimmt ein Live-Foto auf und sendet beide Bilder
  const handleVerifyIdentity = async () => {
    if (!idImage) {
      alert("Bitte lade zuerst ein Foto deines Ausweises hoch!");
      return;
    }

    const imageSrc = webcamRef.current.getScreenshot();
    const liveBlob = await (await fetch(imageSrc)).blob();
    const formData = new FormData();
    formData.append("id_image", idImage);
    formData.append("live_image", liveBlob, "live_image.jpg");

    try {
      const res = await axios.post(
        "http://127.0.0.1:8000/api/students/verify-identity/",
        formData,
        {
          headers: {
            Authorization: `Token ${token}`,
            "Content-Type": "multipart/form-data",
          },
        }
      );

      setVerified(res.data.verified);
      setVerificationMessage(res.data.message);
    } catch (err) {
      console.error(err);
      setVerificationMessage(
        err.response?.data?.message || "Fehler bei der Verifikation."
      );
      setVerified(false);
    }
  };

  // 🧑‍🎓 Wenn Student auf Beitreten klickt
  const joinExam = async (examId) => {
    if (!verified) {
      alert("Bitte führe zuerst die Identitätsprüfung durch!");
      return;
    }

    try {
      const res = await axios.post(
        `http://127.0.0.1:8000/api/students/exams/${examId}/join/`,
        {},
        { headers: { Authorization: `Token ${token}` } }
      );
      alert(res.data.message);
    } catch (err) {
      console.error(err);
      alert("Fehler beim Beitritt zur Prüfung");
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>📋 Prüfungen</h2>
      <ul>
        {exams.map((exam) => (
          <li key={exam.id}>
            {exam.title} – {exam.date}
            <button onClick={() => setSelectedExam(exam)}>Beitreten</button>
          </li>
        ))}
      </ul>

      {selectedExam && (
        <div style={{ marginTop: "30px" }}>
          <h3>🧾 Identitätsprüfung für {selectedExam.title}</h3>

          <div>
            <p>1️⃣ Lade ein Foto deines Studentenausweises hoch:</p>
            <input
              type="file"
              accept="image/*"
              onChange={(e) => setIdImage(e.target.files[0])}
            />
          </div>

          <div style={{ marginTop: "20px" }}>
            <p>2️⃣ Mache ein Live-Foto mit deiner Webcam:</p>
            <Webcam
              ref={webcamRef}
              screenshotFormat="image/jpeg"
              width={320}
              height={240}
            />
          </div>

          <div style={{ marginTop: "20px" }}>
            <button onClick={handleVerifyIdentity}>Identität prüfen</button>
          </div>

          {verificationMessage && (
            <p
              style={{
                color: verified ? "green" : "red",
                fontWeight: "bold",
                marginTop: "10px",
              }}
            >
              {verificationMessage}
            </p>
          )}

          <div style={{ marginTop: "30px" }}>
            <button
              onClick={() => joinExam(selectedExam.id)}
              disabled={!verified}
            >
              Prüfung beitreten
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default JoinExam;
